vAO = uAOTable[ao] / 255.0;
vIsFluid = float(isFluid);
vIsGreedy = float(isGreedy);
vIsFluidPane = float(isFluidPane);
vWaterExposed = float(isWaterExposed);
vLight = unpackLight(light & LIGHT_MASK);
